INSERT INTO [Mod] (ID_Producto_Base, ID_Mod, Nombre_Mod, Descripcion_Mod, Tamano_MB) VALUES
  (1, 1, 'MC Command Center', 'Módulo de control total de la población, embarazos, carreras y tiempo para Los Sims 4.', 15.5),
  (1, 2, 'UI Cheats Extension', 'Permite activar trucos haciendo clic en las barras de necesidades, habilidades y relaciones.', 5.2),
  (1, 3, 'WonderfulWhims', 'Añade relaciones complejas, atracción personal y una personalidad más profunda a los Sims.', 22.0),
  (1, 4, 'Better BuildBuy', 'Amplía el modo construcción con objetos ocultos y herramientas de colocación avanzadas.', 1.2),
  (14, 1, 'Seamless Co-op', 'Permite jugar todo el juego en cooperativo sin las limitaciones del multijugador oficial.', 1.0),
  (14, 2, 'Elden Ring Reforged', 'Revisión del equilibrio, los objetos y la progresión del personaje.', 1000.0),
  (15, 1, 'ImprovedUI', 'Mejora la interfaz con más información y opciones de personalización.', 2.0),
  (15, 2, 'Mod Fixer', 'Permite que los mods que añaden objetos funcionen correctamente.', 1.0),
  (16, 1, 'HD Reworked Project', 'Sustituye texturas y modelos 3D por versiones en alta resolución.', 4500.0),
  (16, 2, 'Fast Travel from Anywhere', 'Permite el viaje rápido desde cualquier punto del mapa, sin necesidad de postes.', 2.1),
  (16, 3, 'Friendly HUD', 'Interfaz configurable con minimapa ampliable y marcadores de misión mejorados.', 6.0),
  (17, 1, 'Cyber Engine Tweaks', 'Framework de scripting y consola de depuración en el que se apoyan la mayoría de mods.', 12.0),
  (17, 2, 'redscript', 'Compilador del lenguaje de scripts del juego, necesario para muchos mods de jugabilidad.', 5.0),
  (17, 3, 'Appearance Menu Mod', 'Herramienta para cambiar la apariencia de personajes, generar NPC y crear escenas fotográficas.', 60.0),
  (18, 1, 'NaturalVision Evolved', 'Modificación gráfica fotorrealista con iluminación, clima y texturas renovadas.', 3000.0),
  (18, 2, 'Menyoo PC', 'Entrenador para generar vehículos, objetos y personajes y editar el mapa en tiempo real.', 10.0),
  (18, 3, 'Script Hook V', 'Biblioteca que permite cargar scripts personalizados en el modo historia.', 1.5),
  (18, 4, 'LSPD First Response', 'Permite jugar como agente de policía de Los Santos con patrullas, detenciones y persecuciones.', 60.0),
  (19, 1, 'Portal Stories: Mel', 'Campaña comunitaria con nueva historia, puzles y voces originales, ambientada antes de Portal.', 3500.0),
  (24, 1, 'Better Balanced Game', 'Ajustes de equilibrio de civilizaciones usados en la escena competitiva.', 5.0),
  (24, 2, 'Sukritact''s Simple UI Adjustments', 'Muestra más información útil en la interfaz sin cambiar la jugabilidad.', 2.0),
  (35, 1, 'Starfield Script Extender (SFSE)', 'Amplía el lenguaje de scripts del juego, requisito de muchos mods.', 1.0),
  (42, 1, 'Qwinn''s Ultimate DAO Fixpack', 'Parche comunitario que corrige cientos de errores de misiones y diálogos.', 20.0),
  (42, 2, 'Dragon Age Redesigned', 'Renueva los rostros y peinados de los personajes principales.', 300.0),
  (49, 1, 'Stracker''s Loader', 'Cargador necesario para muchos mods del juego.', 1.0),
  (51, 1, 'Fallout 3 Wanderers Edition', 'Revisión de la jugabilidad con más realismo, supervivencia y combate rediseñado.', 50.0),
  (51, 2, 'Unofficial Fallout 3 Patch', 'Parche comunitario que corrige errores del juego y de sus expansiones.', 10.0),
  (54, 1, 'FusionFix', 'Corrige errores gráficos y de rendimiento de la versión de PC.', 10.0),
  (64, 1, 'Long War 2', 'Revisión completa de la campaña con misiones de infiltración, más clases y guerra a escala global.', 300.0),
  (64, 2, 'Capnbubs Accessories Pack', 'Añade cientos de piezas de ropa y accesorios para personalizar soldados.', 50.0),
  (66, 1, 'MEUITM', 'Mass Effect Updated/Improved Textures Mod, paquete de texturas en alta resolución.', 3000.0),
  (74, 1, 'Rampage Trainer', 'Entrenador con opciones de jugador, caballos, armas, clima y generación de personajes.', 5.0),
  (74, 2, 'Lenny''s Mod Loader', 'Cargador de scripts necesario para muchos mods del modo historia.', 2.0),
  (81, 1, 'Unofficial Oblivion Patch', 'Parche comunitario que corrige miles de errores del juego.', 10.0),
  (81, 2, 'Oblivion Script Extender (OBSE)', 'Amplía el lenguaje de scripts del juego, requisito de muchos mods.', 1.0),
  (85, 1, 'Sim Settlements 2', 'Permite que los colonos construyan sus asentamientos y añade una nueva historia completa.', 2500.0),
  (85, 2, 'Fallout 4 Script Extender (F4SE)', 'Amplía el lenguaje de scripts del juego, requisito de muchos mods.', 1.0),
  (85, 3, 'Unofficial Fallout 4 Patch', 'Parche comunitario que corrige miles de errores del juego y sus expansiones.', 15.0),
  (85, 4, 'Full Dialogue Interface', 'Muestra el texto completo de las opciones de diálogo en lugar de resúmenes.', 1.0),
  (87, 1, 'NRaas Overwatch', 'Limpia automáticamente datos inútiles de la partida para reducir los retrasos.', 1.0),
  (87, 2, 'NRaas MasterController', 'Control total sobre Sims, familias y barrios desde un único menú.', 2.0),
  (91, 1, 'Cinders', 'Revisión con nuevas clases, armas, hechizos y modos de dificultad.', 300.0),
  (99, 1, 'Tamriel Rebuilt', 'Proyecto comunitario que añade la parte continental de la provincia de Morrowind.', 1500.0),
  (99, 2, 'Morrowind Code Patch', 'Corrige errores del motor y mejora la estabilidad del juego.', 2.0),
  (102, 1, 'Half-Life 2: Update', 'Versión mejorada por la comunidad con iluminación renovada y correcciones.', 1000.0),
  (102, 2, 'Cinematic Mod', 'Renovación gráfica completa con nuevos modelos, texturas e iluminación.', 9000.0),
  (106, 1, 'JSawyer Ultimate Edition', 'Ajustes de equilibrio basados en el mod del director del juego, Josh Sawyer.', 20.0),
  (106, 2, 'Yukichigai Unofficial Patch', 'Parche comunitario que corrige errores del juego y de sus expansiones.', 10.0),
  (106, 3, 'New Vegas Script Extender (NVSE)', 'Amplía el lenguaje de scripts del juego, requisito de muchos mods.', 1.0),
  (127, 1, 'SkyUI', 'Interfaz rediseñada para PC con inventario, menús de magia y favoritos más cómodos.', 3.0),
  (127, 2, 'Unofficial Skyrim Legendary Edition Patch', 'Parche comunitario que corrige miles de errores del juego y sus expansiones.', 60.0),
  (127, 3, 'Skyrim Script Extender (SKSE)', 'Amplía el lenguaje de scripts del juego, requisito de muchos mods.', 1.0),
  (127, 4, 'Alternate Start - Live Another Life', 'Sustituye el inicio del carro por varios orígenes para tu personaje.', 1.5),
  (151, 1, 'Calamity Mod', 'Gran expansión con nuevos jefes, biomas, objetos y niveles de dificultad.', 200.0),
  (151, 2, 'Thorium Mod', 'Añade clases nuevas como el bardo y el sanador, con jefes y objetos propios.', 150.0),
  (151, 3, 'Magic Storage', 'Sistema de almacenamiento centralizado con buscador y fabricación desde el inventario.', 5.0),
  (156, 1, 'SilentPatch', 'Corrige errores de la versión de PC y restaura efectos de la versión original.', 1.0),
  (156, 2, 'CLEO Library', 'Biblioteca que permite cargar scripts personalizados en el juego.', 1.0),
  (163, 1, 'Long War', 'Revisión completa de la campaña con más clases, misiones y una invasión más larga.', 100.0),
  (205, 1, 'Vox Populi (Community Patch Project)', 'Revisión comunitaria de la inteligencia artificial, el equilibrio y los sistemas del juego.', 50.0),
  (205, 2, 'InfoAddict', 'Añade estadísticas y gráficos detallados sobre todas las civilizaciones de la partida.', 1.0);
