INSERT INTO Resena (ID_Resena, ID_Usuario, ID_Producto, Texto_Resena, Calificacion_1_10, Fecha_Publicacion, Es_Critica_Especializada) VALUES
  (1, 6, 91, 'Dark Souls III es una referencia en su género. Destacan sobre todo las misiones secundarias, y la duración está a la altura. Una compra obligada.', 10, '2024-10-20', 1),
  (2, 119, 50, 'God of War Ragnarök es una referencia en su género. Destacan sobre todo los gráficos, y las peleas contra jefes están a la altura. Una compra obligada.', 10, '2024-10-20', 1),
  (3, 196, 17, 'Cyberpunk 2077 cumple con creces lo que promete. La banda sonora es su punto más fuerte, aunque la cantidad de contenido queda un paso por detrás. Recomendable.', 8, '2024-10-20', 1),
  (4, 243, 38, 'Tekken 8 cumple con creces lo que promete. La relación calidad-precio es su punto más fuerte, aunque el equilibrio entre jugadores queda un paso por detrás. Recomendable.', 8, '2024-10-21', 1),
  (5, 187, 143, 'Anthem decepciona en casi todos los apartados. Ni el multijugador ni la relación calidad-precio justifican su precio. Difícil de recomendar en su estado actual.', 4, '2024-10-23', 1),
  (6, 196, 92, 'Fallout 76 decepciona en casi todos los apartados. Ni el rendimiento ni el multijugador justifican su precio. Difícil de recomendar en su estado actual.', 4, '2024-10-23', 1),
  (7, 84, 44, 'Horizon Forbidden West es una referencia en su género. Destaca sobre todo la optimización, y las misiones secundarias están a la altura. Una compra obligada.', 9, '2024-10-25', 1),
  (8, 12, 143, 'Anthem decepciona en casi todos los apartados. Ni los tiroteos ni el manejo de las armas justifican su precio. Difícil de recomendar en su estado actual.', 3, '2024-10-26', 1),
  (9, 12, 60, 'Team Fortress 2 es una referencia en su género. Destacan sobre todo los gráficos, y el manejo de las armas está a la altura. Una compra obligada.', 9, '2024-10-27', 1),
  (10, 133, 30, 'Battlefield 2042 tiene buenas ideas, pero no termina de cuajar. El gunplay funciona, mientras que los tiroteos lastran la experiencia. Solo para seguidores del género.', 5, '2024-10-28', 1),
  (11, 92, 139, 'Dragon Age: Inquisition es una referencia en su género. Destaca sobre todo el mundo abierto, y la libertad para explorar está a la altura. Una compra obligada.', 9, '2024-10-29', 1),
  (12, 96, 71, 'Kingdom Hearts III es una referencia en su género. Destaca sobre todo la duración, y la banda sonora está a la altura. Una compra obligada.', 9, '2024-10-29', 1),
  (13, 119, 143, 'Anthem decepciona en casi todos los apartados. Ni el equilibrio entre jugadores ni el rendimiento justifican su precio. Difícil de recomendar en su estado actual.', 4, '2024-10-29', 1),
  (14, 139, 93, 'Mass Effect 2 es una referencia en su género. Destaca sobre todo la relación calidad-precio, y el gunplay está a la altura. Una compra obligada.', 9, '2024-10-29', 1),
  (15, 243, 70, 'Mafia III cumple con creces lo que promete. Los gráficos son su punto más fuerte, aunque la cantidad de contenido queda un paso por detrás. Recomendable.', 7, '2024-10-30', 1),
  (16, 6, 169, 'The Witcher 2: Assassins of Kings es una referencia en su género. Destaca sobre todo la optimización, y la banda sonora está a la altura. Una compra obligada.', 9, '2024-10-31', 1),
  (17, 62, 13, 'Dark Souls: Remastered cumple con creces lo que promete. La duración es su punto más fuerte, aunque el sistema de rol queda un paso por detrás. Recomendable.', 8, '2024-11-03', 1),
  (18, 84, 35, 'Starfield es una referencia en su género. Destaca sobre todo la progresión del personaje, y el mundo abierto está a la altura. Una compra obligada.', 9, '2024-11-04', 1),
  (19, 119, 87, 'Los Sims 3 es una referencia en su género. Destaca sobre todo la duración, y la relación calidad-precio está a la altura. Una compra obligada.', 10, '2024-11-04', 1),
  (20, 31, 15, 'Baldur''s Gate 3 es una referencia en su género. Destaca sobre todo jugar con amigos, y la inteligencia artificial rival está a la altura. Una compra obligada.', 9, '2024-11-07', 1),
  (21, 229, 84, 'Muy buen juego. El nivel de detalle está muy bien, aunque la banda sonora podría mejorar.', 8, '2024-11-07', 0),
  (22, 6, 175, 'Resident Evil 6 cumple con creces lo que promete. La tensión constante es su punto más fuerte, aunque el rendimiento queda un paso por detrás. Recomendable.', 7, '2024-11-08', 1),
  (23, 139, 112, 'Dark Souls II: Scholar of the First Sin cumple con creces lo que promete. El combate es su punto más fuerte, aunque los gráficos quedan un paso por detrás. Recomendable.', 8, '2024-11-08', 1),
